#!/usr/bin/env node
// Replicate 12 TLEO codes from WS1 MY to WS1 SG.
// T&C auto-generated by igmp-tnc.js (WS1 SG wallet structure, SGD amounts,
// mb8sg.com T&C URL). LC codes → categories: ['Live Casino']. Slots → ['Slots'].

import { igmpPost } from '../src/igmp-client.js';
import { buildIgmpPlan } from '../src/api-mapper-igmp.js';

const SG_SITE = 'ws1-v3-sg';
const NAME_EN = 'Time Limited Exclusive Offer - 45% Reload Bonus';
const NAME_ZH = '限时独家优惠 - 45% 充值奖金';

// All amounts are SGD (same numbers as MYR on WS1).
// categories: ['Live Casino'] for LC_, ['Slots'] for plain Slots codes.
const SOURCES = [
  // Slots Silver
  { code: 'FT_REL_TLEO_45PCT_228MX',       minDep: 500,  cap: 228, rate: 45, to: 3, cats: ['Slots'] },
  { code: 'FT_REL_TLEO_45PCT_458MX',        minDep: 1000, cap: 458, rate: 45, to: 3, cats: ['Slots'] },
  { code: 'FT_REL_TLEO_45PCT_888MX',        minDep: 2000, cap: 888, rate: 45, to: 3, cats: ['Slots'] },
  { code: 'FT_REL_TLEO_45PCT_688MX',        minDep: 1500, cap: 688, rate: 45, to: 3, cats: ['Slots'] },
  // Slots Bronze
  { code: 'FT_REL_TLEO_20PCT_300MX_BR',     minDep: 1500, cap: 300, rate: 20, to: 3, cats: ['Slots'] },
  { code: 'FT_REL_TLEO_20PCT_400MX_BR',     minDep: 2000, cap: 400, rate: 20, to: 3, cats: ['Slots'] },
  // LC Silver
  { code: 'FT_REL_TLEO_LC_45PCT_138MX',     minDep: 300,  cap: 138, rate: 45, to: 8, cats: ['Live Casino'] },
  // LC Bronze
  { code: 'FT_REL_TLEO_LC_45PCT_228MX_BR',  minDep: 500,  cap: 228, rate: 45, to: 8, cats: ['Live Casino'] },
  { code: 'FT_REL_TLEO_LC_45PCT_458MX_BR',  minDep: 1000, cap: 458, rate: 45, to: 8, cats: ['Live Casino'] },
  { code: 'FT_REL_TLEO_LC_20PCT_20MX_BR',   minDep: 100,  cap: 20,  rate: 20, to: 8, cats: ['Live Casino'] },
  { code: 'FT_REL_TLEO_LC_20PCT_300MX_BR',  minDep: 1500, cap: 300, rate: 20, to: 8, cats: ['Live Casino'] },
  { code: 'FT_REL_TLEO_LC_20PCT_400MX_BR',  minDep: 2000, cap: 400, rate: 20, to: 8, cats: ['Live Casino'] },
];

const today    = new Date();
const endDate  = new Date(today.getFullYear(), 11, 31); // end of year

let saved = 0, skipped = 0, errors = 0;

for (const src of SOURCES) {
  // Idempotency check
  const existing = await igmpPost(SG_SITE, '/PM/GetPromotionInfoByCode', { PromotionCode: src.code }).catch(() => null);
  if (existing?.data?.PromotionId) {
    console.log(`SKIP ${src.code} — already id=${existing.data.PromotionId} on SG`);
    skipped++;
    continue;
  }

  const rec = {
    promo_code:          src.code,
    promotion_name_en:   NAME_EN,
    promotion_name_zh_id: NAME_ZH,
    column_m:            '',
    bonus_pct:           src.rate,
    min_deposit:         src.minDep,
    cap_bonus_amount:    src.cap,
    turnover_multiplier: src.to,
    expiry_minutes_ws1:  1440,
    validity_days:       1,
    rewards_validity_days: 1,
    region:              'SG',
    regions:             ['SG'],
    currencies:          ['SGD'],
    locales:             ['SG_EN', 'SG_ZH'],
    categories:          src.cats,
    parsed: {
      bonus_rate_pct:    src.rate,
      min_deposit:       src.minDep,
      max_bonus:         src.cap,
      to_multiplier:     src.to,
      categories:        src.cats,
    },
    bonus_type:      'Deposit',
    __site_override: SG_SITE,   // tells igmp-tnc to use SGD + mb8sg.com URLs
    start_date: today.toISOString().slice(0, 10),
    end_date:   endDate.toISOString().slice(0, 10),
  };

  try {
    const plan = await buildIgmpPlan(rec, { siteId: SG_SITE });
    const res  = await igmpPost(SG_SITE, plan.endpoint, plan.body);
    const newId = res?.data?.PromotionId || res?.PromotionId;
    if (!newId) throw new Error(`No PromotionId in response: ${JSON.stringify(res).slice(0, 200)}`);
    console.log(`✓ ${src.code} → SG id=${newId} [${src.cats[0]}, TO=${src.to}x, min=${src.minDep}, cap=${src.cap}]`);
    saved++;
  } catch (e) {
    console.error(`✗ ${src.code}: ${e.message.slice(0, 120)}`);
    errors++;
  }
}

console.log(`\nDone: ${saved} saved, ${skipped} skipped, ${errors} errors`);

// QC
console.log('\nQC:');
console.log('Code'.padEnd(38) + 'SG ID'.padEnd(8) + 'Active');
console.log('─'.repeat(55));
for (const src of SOURCES) {
  const r = await igmpPost(SG_SITE, '/PM/GetPromotionInfoByCode', { PromotionCode: src.code }).catch(() => null);
  const id = r?.data?.PromotionId || '-';
  const active = r?.data?.IsActive ? 'active' : (id === '-' ? 'NOT FOUND' : 'inactive');
  console.log(src.code.padEnd(38) + String(id).padEnd(8) + active);
}
